"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["9942"],{28979(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.regra_nao_encontrada","status":422,"titulo":"Regra n\xe3o encontrada no cat\xe1logo de regras"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.regra_nao_encontrada","requisitos":[],"oQueAconteceu":["O par c\xf3digo/vers\xe3o declarado para uma das tr\xeas regras que a configura\xe7\xe3o de\\nclassifica\xe7\xe3o referencia \u2014 a regra de c\xe1lculo (`regraCalculoCodigo`/\\n`regraCalculoVersao`), a de arredondamento\\n(`regraArredondamentoCodigo`/`regraArredondamentoVersao`, quando informada)\\nou a de ordem de aloca\xe7\xe3o (`regraOrdemAlocacaoCodigo`/\\n`regraOrdemAlocacaoVersao`) \u2014 n\xe3o existe no `rol_de_regras`. Este \xfanico\\nc\xf3digo cobre a mesma falha nos tr\xeas pontos: o processamento resolve uma\\nregra de cada vez, na ordem c\xe1lculo \u2192 arredondamento \u2192 ordem de aloca\xe7\xe3o, e\\npara na primeira que n\xe3o for encontrada.","Por isso nunca acumula com nenhuma outra causa desta s\xe9rie \u2014 \xe9 sempre a\\nprimeira falha que interrompe o processamento, e a mensagem devolvida cita\\no c\xf3digo e a vers\xe3o que n\xe3o foram encontrados, o que identifica qual das\\ntr\xeas regras \xe9 a origem.","Este c\xf3digo tamb\xe9m \xe9 levantado, com o mesmo nome, para as regras de\\nelimina\xe7\xe3o \u2014 mas ali \xe9 uma causa pr\xf3pria de `RegraEliminacao` (ver\\n[`uniplus.selecao.regra_eliminacao.regra_nao_encontrada`](/erros/uniplus.selecao.regra_eliminacao.regra_nao_encontrada)),\\nn\xe3o esta."],"comoResolver":["Confirme, no cat\xe1logo de regras, que o c\xf3digo e a vers\xe3o declarados existem\\npara a regra de c\xe1lculo, de arredondamento e de ordem de aloca\xe7\xe3o. Se a\\ninten\xe7\xe3o era outra regra do m\xf3dulo (desempate, elimina\xe7\xe3o, distribui\xe7\xe3o de\\nvagas), reveja qual refer\xeancia pertence a qual campo do corpo do pedido."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);